WITH exploded AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) t AS element) SELECT CASE WHEN element >= 61 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, MIN(element) AS min_element, AVG(element) AS avg_element, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS element_per_thb, COUNT(*) FILTER (WHERE currency = 'EUR') AS eur_rows FROM exploded GROUP BY CASE WHEN element >= 61 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) > 0 ORDER BY element_per_thb DESC NULLS FIRST;
